def decode(background=0, foreground=255):
    result = bytearray(WIDTH * HEIGHT)
    offset = 0
    for i in range(0, len(DATA), 3):
        count = DATA[i]
        kind = DATA[i + 2]
        color = foreground if kind == 2 else (background if kind == 1 else DATA[i + 1])
        result[offset:offset + count] = bytes([color]) * count
        offset += count
    return result
